import React, { useState } from 'react';
import { Form, Col, Container, Row } from 'react-bootstrap';
import './RiskForm.css';

const EditableTable = () => {
  const [data, setData] = useState([
    {
      id: 1,
      nombre: '',
      sapcode: '',
    },
  ]);

  const handleInputChange = (id, field, value) => {
    setData((prevData) =>
      prevData.map((item) =>
        item.id === id ? { ...item, [field]: value } : item
      )
    );
  };

  const fields = [
    { label: 'Nombre', field: 'nombre', md: 8 },
    { label: 'Sap Code', field: 'sapcode', md: 4 },
  ];

  return (
    <Container fluid className="mt-3 mb-4 form-container">
      <Form>
        {data.map((item) => (
          <Row key={item.id} className="mb-3">
            {fields.map((field) => (
              <Col key={field.field} md={field.md}>
                <Form.Group controlId={`${field.field}-${item.id}`}>
                  <Form.Label
                    style={{ fontSize: '0.9rem', fontWeight: 'bold' }}
                  >
                    {field.label}
                  </Form.Label>
                  <Form.Control
                    type="text"
                    value={item[field.field]}
                    onChange={(e) =>
                      handleInputChange(item.id, field.field, e.target.value)
                    }
                    style={{ fontSize: '0.8rem' }}
                  />
                </Form.Group>
              </Col>
            ))}
          </Row>
        ))}
      </Form>
    </Container>
  );
};

export default EditableTable;
